mainRecordRcL k r = (\v -> r { mainRecordRc = v }) <$> k (mainRecordRc r)
{-# INLINE mainRecordRcL #-}

mainRecordSeatL :: Lens' MainRecord (Int)
mainRecordSeatL k r = (\v -> r { mainRecordSeat = v }) <$> k (mainRecordSeat r)
{-# INLINE mainRecordSeatL #-}

mainRecordModelL :: Lens' MainRecord (Maybe String)
mainRecordModelL k r = (\v -> r { mainRecordModel = v }) <$> k (mainRecordModel r)
{-# INLINE mainRecordModelL #-}

